reference_solution:
#!/usr/bin/env bash
# colsum.sh FILE COLUMN
if (( $# != 2 )); then
  echo "usage: colsum.sh FILE COLUMN" >&2
  exit 2
fi

awk -F, -v col="$2" '
  { sub(/\r$/, "") }                       # tolerate CRLF line endings
  NR == 1 {
    for (i = 1; i <= NF; i++) if ($i == col) idx = i
    if (!idx) {
      printf "colsum.sh: no column '\''%s'\''\n", col > "/dev/stderr"
      failed = 1
      exit 1                               # END still runs, so it checks `failed`
    }
    next
  }
  {
    v = $idx
    if (v == "") next
    if (v !~ /^-?[0-9]+(\.[0-9]+)?$/) {
      printf "colsum.sh: line %d: not a number: %s\n", NR, v > "/dev/stderr"
      next
    }
    sum += v
  }
  END { if (!failed) printf "%.2f\n", sum }
' "$1"
